function regIcon(name){return '<svg class="reg-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(registryIcons[name]||registryIcons['clipboard-list']).map(([tag,attrs])=>'<'+tag+' '+Object.entries(attrs).map(([key,value])=>key+'="'+String(value).replaceAll('"','&quot;')+'"').join(' ')+'></'+tag+'>').join('')+'</svg>'}
const registryState={date:null,query:'',activity:'',mobile:'',page:1,pageSize:10,filtersOpen:false,station:null,followDate:true};
