const app=document.querySelector('#app');let me,stations=[],mobiles=[],activities=[],locations=[],shifts=[],activeOperation=null,rows=[],view='registros';let disposeReport=null;const recordChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('redeas-registros'):null;if(recordChannel)recordChannel.onmessage=()=>window.dispatchEvent(new Event('redeas:registros'));
