function notice(s){document.querySelector('#notice').textContent=s;setTimeout(()=>document.querySelector('#notice').textContent='',6500)}
async function api(url,method='GET',body){const r=await fetch('/api/'+url,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401)login();throw Error(data.error)}if(method!=='GET'&&/^(registros|servicios|servicio-entrante)(?:\/|$)/.test(url)){recordChannel?.postMessage('changed');window.dispatchEvent(new Event('redeas:registros'))}return data}
function options(items,selected,key='nombre'){return items.map(x=>`<option value="${x.id}" ${Number(selected)===x.id?'selected':''}>${esc(x[key])}</option>`).join('')}
function stationField(id){return `<label>Estación EAS<select name="estacion_id" ${me.rol!=='admin'?'disabled':''}>${options(stations,id||stations[0]?.id)}</select></label>`}
function field(label,name,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''}></label>`}
function login(){clearTimeout(shiftBoundaryTimer);document.body.classList.remove('daily-layout','registry-layout','registry-menu-open','app-layout','weekly-layout','dashboard-layout');resetRegistryState();disposeReport?.();disposeReport=null;me=null;view='registros';app.innerHTML=`<section class="login"><div class="card"><div class="brand">EAS-GO</div><h1>Iniciar sesión</h1><p>Red de Estaciones de Acción Segura</p><form id="login">${field('Usuario','username')}${field('Contraseña','password','','password')}<button>Iniciar sesión →</button></form></div></section>`;document.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('login','POST',Object.fromEntries(new FormData(e.target)));await boot()}catch(e){notice(e.message)}}}
async function boot(){try{me=await api('me')}catch(e){login();return}if(me.rol==='admin'&&['#conexion','#conexion-error'].includes(location.hash)){view='conexion';if(location.hash==='#conexion-error')notice('La autorización de Google no se completó. Revise CONEXIÓN.');history.replaceState({},'',location.pathname)}if(me.rol!=='admin'&&!me.radiooperador){await operatorPopup();return}await render()}
async function render(){disposeReport?.();disposeReport=null;if(!me){login();return}if(me.rol!=='admin'&&!me.radiooperador){await operatorPopup();return}if(me.rol!=='admin'&&!me.servicio_entrante&&view!=='moviles'){await vehicleEntryPopup();return}try{
 if(me.rol!=='admin'){const context=await api('jornada-actual');activeOperation=context;scheduleShiftCheck(context);me.servicio_entrante=context.ingreso_moviles?.completo===true;if(!me.servicio_entrante){await vehicleEntryPopup();return}}
 document.body.classList.add('app-layout');const isReport=['diario','semanal'].includes(view);document.body.classList.toggle('dashboard-layout',view==='dashboard');document.body.classList.toggle('daily-layout',view==='diario');document.body.classList.toggle('weekly-layout',view==='semanal');document.body.classList.toggle('registry-layout',view==='registros');if(view!=='registros')document.body.classList.remove('registry-menu-open');
 if(isReport||view==='informes'||view==='dashboard'||view==='conexion'){stations=await api('estaciones');rows=[];if(view==='informes')activeOperation=await api('jornada-actual')}else{
 [stations,mobiles,activities,locations,shifts,activeOperation]=await Promise.all([api('estaciones'),api('moviles'),api('actividades'),api('ubicaciones'),api('jornadas'),api('jornada-actual')]);
 rows=await api(view==='actividades'?'actividades?all':view==='radiooperadores'&&me.rol==='admin'?'radiooperadores?all=1':view);}
 if(activeOperation)scheduleShiftCheck(activeOperation);
 if(view==='moviles'&&me.rol!=='admin'&&!me.servicio_entrante&&mobiles.length){await vehicleEntryPopup();return}
 if(view==='registros'){renderRegistry();return}
 const titles={conexion:'Administración → CONEXIÓN',dashboard:'Dashboard Operativo',informes:'Informes',diario:'Consolidado Diario',semanal:'Consolidado Semanal',registros:'Registro Operativo',moviles:'Móviles',ubicaciones:'Ubicaciones',radiooperadores:'Radiooperadores',actividades:'Administración → Actividades',estaciones:'Administración → Estaciones',usuarios:'Administración → Usuarios'};
 app.innerHTML=`${registrySidebar()}<main><header><div><small>CONTROL MUNICIPAL / ${esc(view==='dashboard'&&me.rol==='admin'?'ADMINISTRACIÓN GENERAL':stations.map(s=>s.nombre).join(' · '))}</small><h1>${titles[view]}</h1><p>Organiza y consulta la información de tu estación.</p></div><div><span class="badge">${me.radiooperador?'Radioperador: '+esc(me.radiooperador?.nombre||'Acceso administrador'):'Acceso administrador'}</span> <span class="badge">${esc(me.username)} · ${esc(me.rol)}</span> <button id="logout" class="secondary">Salir</button></div></header><section class="card"><div class="toolbar"><h2>${view==='registros'?'Operación diaria':'Gestión de '+view}</h2><span>${rows.length} registros</span></div><div id="editor"></div><div class="scroll" id="table"></div></section></main>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelector('#logout').onclick=async()=>{await api('logout','POST');login()};bindTopNavigation();if(view==='conexion'){const {mountConnection}=await import('/consolidados.js?v=oauth-1');disposeReport=mountConnection(document.querySelector('main > .card'),{api,me,stations});return}if(view==='dashboard'){const {mountDashboard}=await import('/consolidados.js?v=oauth-1');disposeReport=mountDashboard(document.querySelector('main > .card'),{api,me,stations,icon:regIcon});return}if(isReport){const {mountConsolidado}=await import('/consolidados.js?v=oauth-1');disposeReport=mountConsolidado(document.querySelector('main > .card'),{type:view,api,esc,options,me,stations});return}if(view==='radiooperadores'){renderRadioDirectory();return}if(view==='informes'){renderReportsCenter();return}editor();table();if(view==='moviles')renderMaintenanceAlerts();
 }catch(e){notice(e.message)}}
function editor(item={}){
 if(view==='radiooperadores'){const heading=document.querySelector('[data-radio-form-title]');if(heading)heading.textContent=item.id?'Editar radioperador':'Nuevo radioperador'}
 let fields='';if(view==='moviles')fields=field('Placa','placa',item.placa)+field('Número de móvil','numero',item.numero)+field('Kilometraje','kilometraje',item.kilometraje??0,'number')+`<label>Combustible<select name="combustible">${['Lleno','3/4','1/2','1/4','Reserva'].map(v=>`<option ${item.combustible===v?'selected':''}>${v}</option>`).join('')}</select></label>`+field('Novedades','novedades',item.novedades,'text',false)+stationField(item.estacion_id);
 if(view==='actividades'||view==='estaciones')fields=field('Nombre','nombre',item.nombre)+colorEditor(item.color);if(view==='actividades'&&item.id)fields+=`<label>Estado<select name="estado"><option value="1" ${item.estado?'selected':''}>Activa</option><option value="0" ${!item.estado?'selected':''}>Inactiva</option></select></label>`;
 if(view==='ubicaciones')fields=field('Nombre de ubicación','nombre',item.nombre)+'<label>Tipo<select name="tipo"><option value="ubicacion">Ubicación</option><option value="consigna">Punto de consigna</option></select></label>'+stationField(item.estacion_id);
 if(view==='radiooperadores')fields=field('Nombre completo del radioperador','nombre',item.nombre)+(me.rol==='admin'?`<label>Estado<select name="estado"><option value="1" ${item.estado!==0?'selected':''}>Habilitado</option><option value="0" ${item.estado===0?'selected':''}>Desactivado</option></select></label><fieldset><legend>Estaciones asignadas</legend>${stations.map(s=>`<label class="station-check"><input type="checkbox" name="estaciones" value="${s.id}" ${(item.estaciones||[item.estacion_id||stations[0]?.id]).includes(s.id)?'checked':''}>${esc(s.nombre)}</label>`).join('')}</fieldset>`:stationField(item.estacion_id));
 if(view==='usuarios')fields=(item.id?'<label>Rol<input readonly value="'+(item.rol==='admin'?'Administrador':'Usuario EAS')+'"></label>':field('Usuario','username')+field('Contraseña (mín. 12 caracteres)','password','','password')+'<label>Rol<select name="rol"><option value="eas">Usuario EAS</option><option value="admin">Administrador</option></select></label>')+'<div data-user-station>'+((item.rol==='admin')?'<label>Estación de referencia (opcional)<select name="estacion_id"><option value="">Sin estación fija</option>'+options(stations,item.estacion_id)+'</select></label>':stationField(item.estacion_id))+'</div><small data-admin-role-help '+(item.rol==='admin'?'':'hidden')+'>El administrador tendrá acceso a todas las estaciones y a la administración del sistema.</small>';
 if(view==='registros')fields=recordFields(item);
 document.querySelector('#editor').innerHTML=`<form class="fields" id="edit">${fields}<button>${item.id?'Guardar cambios':'Crear '+({registros:'registro',moviles:'móvil',ubicaciones:'ubicación',radiooperadores:'radiooperador',actividades:'actividad',estaciones:'estación',usuarios:'usuario'}[view])}</button>${item.id?'<button type="button" id="cancel" class="secondary">Cancelar</button>':''}</form>`;
 const form=document.querySelector('#edit');if(view==='ubicaciones'){form.elements.tipo.value=item.tipo||'ubicacion';if(item.id){form.elements.nombre.readOnly=true;form.elements.estacion_id.disabled=true}}wireStation(form);bindColorEditor(form);if(view==='usuarios'){const role=form.elements.rol,stationGroup=form.querySelector('[data-user-station]'),help=form.querySelector('[data-admin-role-help]');if(role){const update=()=>{const admin=role.value==='admin';stationGroup.hidden=admin;stationGroup.querySelectorAll('select').forEach(select=>select.disabled=admin);help.hidden=!admin;form.querySelector('button:not([type])').textContent=admin?'Crear administrador':'Crear usuario'};role.onchange=update;update()}}form.onsubmit=async e=>{e.preventDefault();await save(form,item.id)};document.querySelector('#cancel')?.addEventListener('click',()=>editor());
}
function shiftDescription(s){return s?s.nombre+' ('+s.hora_inicio+'–'+s.hora_fin+')':'SIN JORNADA'}
function recordFields(r={}){const sid=r.estacion_id||stations[0]?.id;const active=[...activities];if(r.actividad_id&&!active.some(a=>a.id===r.actividad_id))active.push({id:r.actividad_id,nombre:r.actividad_nombre+' (inactiva)'});return `<label>Fecha operativa<input name="fecha" type="date" readonly value="${esc(r.id?r.fecha:activeOperation?.fecha_operativa||'')}" ${r.id?'':'data-auto-date'}></label><label>Jornada<input readonly value="${esc(shiftDescription(r.id?shifts.find(s=>s.id===r.jornada_id):activeOperation?.jornada))}" ${r.id?'':'data-auto-shift'}><small>Asignada por el servidor; se conserva al editar el registro.</small></label>`+`<label>Hora<input name="hora" type="time" step="1" value="${esc(r.hora||'')}"><small>En blanco: automática al crear; se conserva al editar.</small></label>`+stationField(sid)+`<label># de Móvil<select name="movil_id"><option value="">SIN MÓVIL</option>${options(mobiles.filter(m=>m.estacion_id===Number(sid)),r.movil_id,'numero')}</select></label><label>Actividad<select name="actividad_id" required><option value="">Seleccione actividad</option>${options(active,r.actividad_id)}</select></label>`+locationFields(r,sid)+field('Detalle','detalle',r.detalle,'text',false)}
function wireStation(form){form.querySelector('[name=estacion_id]')?.addEventListener('change',e=>{const select=form.querySelector('[name=movil_id]');if(select)select.innerHTML='<option value="">SIN MÓVIL</option>'+options(mobiles.filter(m=>m.estacion_id===Number(e.target.value)),null,'numero');const loc=form.querySelector('[data-location]');if(loc){loc.innerHTML=locationFields({},e.target.value,true);wireLocation(form)}});wireLocation(form)}
async function save(form,id){try{const data=Object.fromEntries(new FormData(form));delete data.color_hex;if(view==='registros'){const hour=form.querySelector('[name=hora]');if(!id&&hour?.dataset.userEdited!=='true')delete data.hora;const selected=form.querySelector('[name=ubicacion_id]');if(selected?.value==='new'){const nombre=form.querySelector('[name=nueva_ubicacion]').value.trim();if(!nombre)throw Error('Escriba el nombre de la nueva ubicación');const location=await api('ubicaciones','POST',{nombre,estacion_id:data.estacion_id||me.estacion_id});locations.push(location);selected.insertAdjacentHTML('beforeend',options([location],location.id));selected.value=String(location.id);data.ubicacion_id=String(location.id);wireLocation(form)}else if(!selected?.value)data.ubicacion='';if(data.ubicacion_id==='legacy')delete data.ubicacion_id;delete data.nueva_ubicacion;}if(me.rol!=='admin')data.estacion_id=me.estacion_id;if(view==='actividades')data.estado=Number(data.estado??1);if(view==='radiooperadores'&&me.rol==='admin'){data.estado=Number(data.estado);data.estaciones=new FormData(form).getAll('estaciones').map(Number);}await api(view+(id?'/'+id:''),id?'PUT':'POST',data);notice('Cambios guardados');if(view==='radiooperadores')me=await api('me');await render()}catch(e){notice(e.message)}}
function table(){const target=document.querySelector('#table');if(!rows.length){target.innerHTML='<div class="empty">Aún no hay registros. Utiliza el formulario para crear el primero.</div>';return}
 const cols={radiooperadores:[['nombre','Radioperador'],['estado','Estado'],['estaciones','Estaciones asignadas'],['creado','Creación']],ubicaciones:[['nombre','Ubicación'],['tipo','Tipo'],['estacion_id','EAS']],moviles:[['placa','Placa'],['numero','# Móvil'],['conductor','Conductor'],['jefe_patrulla','Jefe de patrulla'],['kilometraje','Kilometraje'],['mantenimiento_aceite','Cambio de aceite'],['combustible','Combustible'],['novedades','Novedades'],['estacion_id','EAS']],actividades:[['nombre','Actividad'],['color','Color'],['estado','Estado'],['creado','Creación'],['modificado','Modificación']],estaciones:[['nombre','Estación'],['color','Color']],usuarios:[['username','Usuario'],['rol','Rol'],['estacion_id','Estación']],registros:[['fecha','Fecha'],['hora','Hora'],['jornada_id','Jornada'],['estacion_id','EAS'],['movil_id','# Móvil'],['actividad_nombre','Actividad'],['ubicacion','Ubicación'],['detalle','Detalle']]}[view];
 target.innerHTML=`<table><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}<th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr data-id="${r.id}">${cols.map(([k])=>`<td>${k==='mantenimiento_aceite'?maintenanceCell(r):k==='color'?`<span class="entity-color-preview" data-entity-color="${validColor(r.color)}">${validColor(r.color)}</span>`:esc(k==='rol'?(r.rol==='admin'?'Administrador':'Usuario EAS'):k==='jornada_id'?(shifts.find(s=>s.id===r.jornada_id)?.nombre||'SIN JORNADA'):k==='estaciones'?(r.estaciones||[r.estacion_id]).map(id=>stations.find(s=>s.id===id)?.nombre).filter(Boolean).join(', '):k==='hora'?(r.hora||'No disponible'):k==='estacion_id'?(stations.find(s=>s.id===r[k])?.nombre||(view==='usuarios'&&r.rol==='admin'?'Todas las estaciones':'—')):k==='movil_id'?(mobiles.find(m=>m.id===r[k])?.numero||'SIN MÓVIL'):k==='estado'?(r[k]?'Activa':'Inactiva'):r[k])}</td>`).join('')}<td>${(view==='radiooperadores'&&me.rol!=='admin')?'':`<button class="secondary" data-edit="${r.id}">${view==='ubicaciones'?'Clasificar':'Editar'}</button>`}${(['actividades','registros'].includes(view)||(view==='usuarios'&&r.id!==me.id))?`<button class="secondary" data-delete="${r.id}">Eliminar</button>`:''}</td></tr>`).join('')}</tbody></table>`;
 applyEntityColors(target);
 target.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=rows.find(x=>x.id===Number(b.dataset.edit));if(view==='registros'){const tr=b.closest('tr');tr.innerHTML=`<td colspan="${cols.length+1}"><form class="fields">${recordFields(r)}<button>Guardar</button><button type="button" class="secondary">Cancelar</button></form></td>`;const f=tr.querySelector('form');wireStation(f);f.onsubmit=e=>{e.preventDefault();save(f,r.id)};f.querySelector('[type=button]').onclick=table}else editor(r)});
 target.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(view==='usuarios'?'¿Eliminar el acceso de este usuario? Dejará de aparecer en la lista y no podrá iniciar sesión. Sus registros históricos se conservarán.':view==='registros'?'¿Eliminar este registro operativo? Esta acción no se puede deshacer.':'¿Eliminar esta actividad? Solo se eliminará si no tiene registros asociados.'))return;try{await api(view+'/'+b.dataset.delete,'DELETE');await render()}catch(e){notice(e.message)}});
}

function locationFields(r,sid,inner=false){
 const list=locations.filter(l=>l.estacion_id===Number(sid));const selected=list.find(l=>l.nombre===r.ubicacion);
 const content=`<label>Ubicación<select name="ubicacion_id"><option value="">Seleccione ubicación</option>${options(list,selected?.id)}${r.ubicacion&&!selected?`<option value="legacy" selected>${esc(r.ubicacion)} (guardada)</option>`:''}<option value="new">+ Agregar nueva ubicación</option></select></label><label data-new-location hidden>Nueva ubicación<input name="nueva_ubicacion" maxlength="2000" disabled></label>`;
 return inner?content:`<div data-location>${content}</div>`;
}
function wireLocation(form){const select=form.querySelector('[name=ubicacion_id]');if(!select)return;const update=()=>{const label=form.querySelector('[data-new-location]'),input=label.querySelector('input'),isNew=select.value==='new';label.hidden=!isNew;input.disabled=!isNew;input.required=isNew};select.onchange=update;update()}

async function operatorPopup(){
 try{
  const [list,eas]=await Promise.all([api('radiooperadores'),api('estaciones')]);
  app.innerHTML='<section class="login"><div class="card"><div class="brand">EAS-GO</div><p>Identificación del radiooperador entrante</p></div></section>';
  const dialog=document.createElement('dialog');dialog.className='operator-dialog';dialog.setAttribute('aria-labelledby','operator-title');
  dialog.innerHTML=`<form id="operator-form"><div class="brand">EAS-GO</div><label>Estación EAS<select name="estacion_id" ${me.rol!=='admin'?'disabled':''}>${options(eas,me.estacion_id||eas[0]?.id)}</select></label><div id="operator-fields"></div><p id="operator-error" role="alert"></p><button type="submit">Siguiente</button><button type="button" class="secondary" id="operator-logout">Cerrar sesión</button></form>`;
  app.append(dialog);const form=dialog.querySelector('form'),station=form.querySelector('[name=estacion_id]');
  function refresh(){const names=list.filter(o=>(o.estaciones||[o.estacion_id]).includes(Number(station.value)));const host=form.querySelector('#operator-fields');host.innerHTML=names.length?`<h2 id="operator-title">Radiooperador entrante</h2><label>Seleccione su nombre<select name="radiooperador_id" required><option value="">Seleccione radiooperador</option>${options(names)}<option value="new">+ Agregar nuevo radiooperador</option></select></label><label data-new-operator hidden>AGREGAR NUEVO RADIOPERADOR<input name="nombre" maxlength="150" disabled></label>`:`<h2 id="operator-title">AGREGAR NUEVO RADIOPERADOR</h2><label>Nombre del radiooperador<input name="nombre" maxlength="150" required autocomplete="name"></label>`;
   const select=host.querySelector('select');if(select)select.onchange=()=>{const label=host.querySelector('[data-new-operator]'),input=label.querySelector('input'),isNew=select.value==='new';label.hidden=!isNew;input.disabled=!isNew;input.required=isNew};form.querySelector('#operator-error').textContent='';
  }
  station.onchange=refresh;refresh();dialog.addEventListener('cancel',e=>e.preventDefault());dialog.showModal();
  form.querySelector('#operator-logout').onclick=async()=>{try{await api('logout','POST');login()}catch(e){form.querySelector('#operator-error').textContent=e.message}};
  form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{let selected=form.querySelector('[name=radiooperador_id]');let id=selected?.value;if(!selected||id==='new'){const created=await api('radiooperadores','POST',{nombre:form.querySelector('[name=nombre]').value,estacion_id:Number(station.value)});list.push(created);refresh();selected=form.querySelector('[name=radiooperador_id]');selected.value=String(created.id);id=created.id}me.radiooperador=await api('radiooperador-entrante','POST',{radiooperador_id:id});me.servicio_entrante=false;dialog.close();dialog.remove();if(me.rol==='admin')await render();else await vehicleEntryPopup()}catch(e){form.querySelector('#operator-error').textContent=e.message}finally{button.disabled=false}};
 }catch(e){notice(e.message);app.innerHTML='<section class="login"><div class="card"><h1>No se pudo cargar el radiooperador</h1><button id="retry-operator">Reintentar</button></div></section>';document.querySelector('#retry-operator').onclick=operatorPopup}
}

boot();


function scheduleShiftCheck(context){clearTimeout(shiftBoundaryTimer);if(!me)return;const seconds=context.hora_local.split(':').reduce((n,v)=>n*60+Number(v),0);const next=[21600,50400,79200,108000].find(value=>value>seconds);shiftBoundaryTimer=setTimeout(syncOperationContext,Math.max(100,(next-seconds)*1000+100))}
async function syncOperationContext(){
 if(!me||document.hidden||shiftSyncBusy||(me.rol!=='admin'&&!me.radiooperador))return;shiftSyncBusy=true;const uid=me.id;
 try{const context=await api('jornada-actual');if(!me||me.id!==uid)return;activeOperation=context;scheduleShiftCheck(context);
  if(me.rol!=='admin'){me.servicio_entrante=context.ingreso_moviles?.completo===true;const popup=document.querySelector('.vehicle-entry-dialog');if(popup&&popup.dataset.jornadaClave!==context.ingreso_moviles?.clave)await popup.reloadForShift?.();else if(!popup&&!me.servicio_entrante){await vehicleEntryPopup();return}}
  if(view==='registros'){const date=document.querySelector('#edit [data-auto-date]');if(date)date.value=context.fecha_operativa;if(document.body.classList.contains('registry-layout'))updateRegistryContext();await refreshRegistryMaintenance()}
 }catch{}finally{shiftSyncBusy=false}
}
setInterval(syncOperationContext,15000);window.addEventListener('focus',syncOperationContext);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncOperationContext()});

function resetRegistryState(){Object.assign(registryState,{date:null,query:'',activity:'',mobile:'',page:1,pageSize:10,filtersOpen:false,station:null,followDate:true})}
function registryStation(){return me.rol==='admin'?Number(registryState.station||me.radiooperador?.estacion_id||stations[0]?.id):me.estacion_id}
function regDate(value){return value?value.split('-').reverse().join('/'):'—'}
function registrySidebar(){
 const link=(target,label,icon)=>`<button type="button" data-view="${target}" class="${target===view?'active':''}" ${target===view?'aria-current="page"':''}>${regIcon(icon)}<span>${label}</span></button>`;
 const station=registryStation();
 return `<button type="button" class="reg-menu-backdrop" aria-label="Cerrar menú" data-close-menu></button><aside class="reg-sidebar reg-topnav" aria-label="Navegación principal"><div class="reg-sidebar-brand"><span class="reg-brand-mark">${regIcon('shield-check')}</span><div class="brand">EAS-GO<small>Estaciones de Acción Segura</small></div></div><button type="button" class="reg-top-toggle" data-menu-toggle aria-label="Abrir menú" aria-expanded="false">${regIcon('menu')}</button><nav>${link('registros','Registro Operativo','clipboard-list')}${link('diario','Consolidado Diario','calendar-days')}${link('semanal','Consolidado Semanal','chart-no-axes-combined')}${link('moviles','Móviles','truck')}${link('ubicaciones','Ubicaciones','map-pin')}${link('radiooperadores','Radioperadores','radio')}${me.rol==='admin'?link('estaciones','Estaciones EAS','building-2')+link('actividades','Actividades','list')+link('usuarios','Usuarios','users')+link('conexion','CONEXIÓN','settings'):''}${link('dashboard','Dashboard Operativo','chart-no-axes-combined')}${link('informes','Informes','clipboard-list')}</nav><div class="reg-station-context">${regIcon('building-2')}<div><small>ESTACIÓN EAS</small>${me.rol==='admin'&&view==='registros'?`<select aria-label="Estación de trabajo" data-work-station>${options(stations,station)}</select>`:`<strong>${esc(stations.find(s=>s.id===station)?.nombre||(me.rol==='admin'?'ADMINISTRACIÓN':''))}</strong>`}</div></div></aside>`;
}
function bindTopNavigation(){
 const theme=stations.find(s=>s.id===Number(me.rol==='admin'?registryStation():me.estacion_id));applyStationTheme(theme?.color);
 const sidebar=app.querySelector('.reg-sidebar'),toggle=app.querySelector('[data-menu-toggle]');if(!sidebar||!toggle)return;
 const mobile=window.matchMedia('(max-width:900px)');
 function menu(open){document.body.classList.toggle('registry-menu-open',open);toggle.setAttribute('aria-expanded',String(open));sidebar.inert=false;sidebar.querySelector('nav').inert=mobile.matches&&!open}
 toggle.onclick=()=>menu(!document.body.classList.contains('registry-menu-open'));app.querySelector('[data-close-menu]').onclick=()=>menu(false);menu(false);
}
function renderRegistry(){
 if(!registryState.date)registryState.date=activeOperation.fecha_operativa;
 registryState.station=registryStation();
 const activityFilters=new Map(rows.map(r=>[r.actividad_id,{id:r.actividad_id,nombre:r.actividad_nombre}]));for(const activity of activities)activityFilters.set(activity.id,activity);
 app.innerHTML=`${registrySidebar()}<main class="reg-main"><header class="reg-header"><div class="reg-header-title"><span class="reg-title-icon">${regIcon('clipboard-list')}</span><div><h1>Registro Operativo</h1><p>Registra y consulta las actividades realizadas en tu estación.</p></div></div><div class="reg-user-context"><span class="reg-operator">${regIcon('radio')}<span>${esc(me.radiooperador?.nombre||'Acceso administrador')}</span></span><span class="reg-user">${esc(me.username)} · ${esc(me.rol)}</span><button type="button" id="logout" class="reg-logout" title="Salir">${regIcon('log-out')}<span>Salir</span></button></div></header><section class="reg-info-strip" aria-label="Información operativa actual"><article class="reg-info-date"><span class="reg-info-icon">${regIcon('calendar-days')}</span><div><span>Fecha operativa</span><strong data-reg-date></strong></div></article><article class="reg-info-shift"><span class="reg-info-icon" data-reg-shift-icon></span><div><span>Jornada actual (según hora del sistema)</span><strong data-reg-shift></strong></div></article><article class="reg-info-clock"><span class="reg-info-icon">${regIcon('clock-3')}</span><div><span>Hora actual</span><strong data-reg-clock></strong><small>America/Guayaquil</small></div></article></section><section class="reg-card reg-new-card"><h2><span class="reg-section-icon">${regIcon('plus')}</span>Nuevo registro operativo</h2><div id="registry-editor"></div></section><section class="reg-card reg-list-card"><div class="reg-list-heading"><h2><span class="reg-section-icon">${regIcon('list')}</span>Registros del día <small data-record-count></small></h2><div class="reg-list-tools"><label class="reg-search">${regIcon('search')}<input type="search" data-record-search aria-label="Buscar registros" placeholder="Buscar por actividad, ubicación o detalle…" value="${esc(registryState.query)}"></label><label class="reg-date-filter">${regIcon('calendar-days')}<input type="date" data-record-date aria-label="Filtrar por fecha operativa" value="${esc(registryState.date)}"></label><button type="button" data-today class="reg-tool-button">${regIcon('calendar-days')}<span>Hoy</span></button><button type="button" data-filters class="reg-tool-button" aria-expanded="${registryState.filtersOpen}" aria-controls="registry-filters">${regIcon('list-filter')}<span>Filtros</span>${regIcon('chevron-down')}</button><button type="button" data-refresh-records class="reg-tool-button reg-square" title="Actualizar registros" aria-label="Actualizar registros">${regIcon('refresh-cw')}</button></div></div><div id="registry-filters" class="reg-extra-filters" ${registryState.filtersOpen?'':'hidden'}><label>Actividad<select data-filter-activity><option value="">Todas las actividades</option>${options([...activityFilters.values()],registryState.activity)}</select></label><label>Móvil<select data-filter-mobile><option value="">Todos los móviles</option><option value="none" ${registryState.mobile==='none'?'selected':''}>SIN MÓVIL</option>${options(mobiles.filter(m=>m.estacion_id===registryStation()),registryState.mobile,'numero')}</select></label><button type="button" class="reg-tool-button" data-reset-filters>Limpiar filtros</button></div><div id="registry-table" class="reg-table-scroll" aria-label="Registros operativos"></div><div class="reg-table-footer"><span data-record-range></span><nav aria-label="Paginación de registros" data-reg-pagination></nav></div></section></main>`;
 app.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{view=button.dataset.view;document.body.classList.remove('registry-menu-open');render()});
 app.querySelector('#logout').onclick=async()=>{try{await api('logout','POST');login()}catch(e){notice(e.message)}};
 bindTopNavigation();
 app.querySelector('[data-work-station]')?.addEventListener('change',e=>{registryState.station=Number(e.target.value);registryState.page=1;registryState.mobile='';registryState.activity='';renderRegistry()});
 app.querySelector('[data-record-search]').oninput=e=>{registryState.query=e.target.value;registryState.page=1;renderRegistryTable()};
 app.querySelector('[data-record-date]').onchange=e=>{registryState.date=e.target.value||activeOperation.fecha_operativa;registryState.followDate=false;registryState.page=1;renderRegistryTable()};
 app.querySelector('[data-today]').onclick=async()=>{try{activeOperation=await api('jornada-actual');registryState.followDate=true;registryState.date=activeOperation.fecha_operativa;registryState.page=1;app.querySelector('[data-record-date]').value=registryState.date;updateRegistryContext();renderRegistryTable()}catch(e){notice(e.message)}};
 app.querySelector('[data-filters]').onclick=e=>{registryState.filtersOpen=!registryState.filtersOpen;app.querySelector('#registry-filters').hidden=!registryState.filtersOpen;e.currentTarget.setAttribute('aria-expanded',String(registryState.filtersOpen))};
 app.querySelector('[data-filter-activity]').onchange=e=>{registryState.activity=e.target.value;registryState.page=1;renderRegistryTable()};app.querySelector('[data-filter-mobile]').onchange=e=>{registryState.mobile=e.target.value;registryState.page=1;renderRegistryTable()};
 app.querySelector('[data-reset-filters]').onclick=()=>{registryState.activity='';registryState.mobile='';registryState.query='';registryState.page=1;app.querySelector('[data-filter-activity]').value='';app.querySelector('[data-filter-mobile]').value='';app.querySelector('[data-record-search]').value='';renderRegistryTable()};
 app.querySelector('[data-refresh-records]').onclick=refreshRegistryRows;
 renderRegistryForm();renderRegistryTable();updateRegistryContext();renderRegistryMaintenance();
}
function registryFields(r={}){
 const sid=r.estacion_id||registryStation(),formId=r.id||'new',active=[...activities];if(r.actividad_id&&!active.some(a=>a.id===r.actividad_id))active.push({id:r.actividad_id,nombre:r.actividad_nombre+' (inactiva)'});
 const local=locations.filter(l=>l.estacion_id===sid),selected=local.find(l=>l.nombre===r.ubicacion);
 return `<input type="hidden" name="estacion_id" value="${sid}"><div class="reg-form-row reg-form-top"><label>Fecha operativa<input type="date" name="fecha" value="${esc(r.id?r.fecha:activeOperation.fecha_operativa)}" readonly ${r.id?'':'data-auto-date'}></label><label>Hora<input type="time" name="hora" step="1" value="${esc(r.id?r.hora||'':activeOperation.hora_local)}" ${r.id?'':'data-auto-hour'}></label><label># de Móvil<select name="movil_id" aria-label="# de Móvil"><option value="">Seleccione móvil (SIN MÓVIL)</option>${options(mobiles.filter(m=>m.estacion_id===sid),r.id?r.movil_id:me.movil_entrante_id,'numero')}</select></label></div><div class="reg-form-row reg-form-bottom"><label><span class="reg-label-activity">${regIcon('clipboard-list')}Actividad</span><select name="actividad_id" required><option value="">Seleccione actividad</option>${options(active,r.actividad_id)}</select></label><div class="reg-location" data-location><label for="reg-location-${formId}"><span class="reg-label-location">${regIcon('map-pin')}Ubicación</span></label><div class="reg-location-controls"><select id="reg-location-${formId}" name="ubicacion_id"><option value="">Seleccione ubicación</option>${options(local,selected?.id)}${r.ubicacion&&!selected?`<option value="legacy" selected>${esc(r.ubicacion)} (guardada)</option>`:''}<option value="new">+ Agregar nueva ubicación</option></select><button type="button" data-add-location class="reg-map-button" title="Agregar nueva ubicación" aria-label="Agregar nueva ubicación">${regIcon('map')}</button></div><label data-new-location hidden>Nueva ubicación<input name="nueva_ubicacion" maxlength="2000" disabled></label></div><label><span class="reg-label-detail">${regIcon('notebook-pen')}Detalle / Observación</span><textarea name="detalle" rows="1" maxlength="2000" placeholder="Ingrese el detalle de la actividad…">${esc(r.detalle||'')}</textarea><small class="reg-character-count" data-character-count>${(r.detalle||'').length}/2000</small></label></div>`;
}
function renderRegistryForm(){
 const target=document.querySelector('#registry-editor');if(!target)return;
 target.innerHTML=`<form id="edit" class="reg-record-form">${registryFields()}<div class="reg-form-actions"><button type="button" data-clear-record class="reg-clear-button" title="Limpiar formulario" aria-label="Limpiar formulario">${regIcon('brush-cleaning')}</button><button type="submit" class="reg-create-button">${regIcon('plus')}Crear registro</button></div></form>`;
 const form=target.querySelector('form');bindRegistryForm(form);form.querySelector('[data-clear-record]').onclick=()=>renderRegistryForm();
}
function bindRegistryForm(form,id){
 const activitySelect=form.elements.actividad_id;function colorSelectedActivity(){activitySelect.dataset.entityColor=validColor(activities.find(a=>a.id===Number(activitySelect.value))?.color);activitySelect.classList.toggle('entity-selected-activity',!!activitySelect.value);applyEntityColors(form)}activitySelect.onchange=colorSelectedActivity;colorSelectedActivity();
 wireLocation(form);form.querySelector('[data-add-location]').onclick=()=>{const select=form.querySelector('[name=ubicacion_id]');select.value='new';select.dispatchEvent(new Event('change'));form.querySelector('[name=nueva_ubicacion]').focus()};
 form.querySelector('[name=detalle]').oninput=e=>{form.querySelector('[data-character-count]').textContent=e.target.value.length+'/2000'};
 form.querySelector('[name=hora]').oninput=e=>{e.target.dataset.userEdited='true'};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await save(form,id)}finally{button.disabled=false}};
}
function registryMatches(){
 const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),query=normalize(registryState.query);
 return rows.filter(r=>r.estacion_id===registryStation()&&r.fecha===registryState.date&&(!registryState.activity||r.actividad_id===Number(registryState.activity))&&(!registryState.mobile||(registryState.mobile==='none'?r.movil_id===null:r.movil_id===Number(registryState.mobile)))&&(!query||normalize([r.actividad_nombre,r.ubicacion,r.detalle,mobiles.find(m=>m.id===r.movil_id)?.numero].join(' ')).includes(query)));
}
function registryActivityIcon(name){const key=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();return key.includes('PARAMEDICA')?['circle-plus','medical']:key.includes('BASURA')||key.includes('DESECHOS')?['trash-2','waste']:key==='OPERATIVOS'?['shield-check','operation']:['clipboard-list','default']}
function renderRegistryTable(){
 const host=document.querySelector('#registry-table');if(!host)return;const filtered=registryMatches(),pages=Math.max(1,Math.ceil(filtered.length/registryState.pageSize));registryState.page=Math.min(registryState.page,pages);
 const from=(registryState.page-1)*registryState.pageSize,page=filtered.slice(from,from+registryState.pageSize);
 document.querySelector('[data-record-count]').textContent=`(${filtered.length} ${filtered.length===1?'registro':'registros'})`;
 host.innerHTML=`<table class="reg-record-table"><colgroup><col class="reg-col-date"><col class="reg-col-hour"><col class="reg-col-mobile"><col class="reg-col-activity"><col class="reg-col-location"><col class="reg-col-detail"><col class="reg-col-actions"></colgroup><thead><tr>${['FECHA','HORA','# MÓVIL','ACTIVIDAD','UBICACIÓN','DETALLE','ACCIONES'].map(name=>`<th scope="col">${name}</th>`).join('')}</tr></thead><tbody>${page.length?page.map(r=>{const [icon,color]=registryActivityIcon(r.actividad_nombre);return `<tr data-reg-id="${r.id}"><td>${esc(r.fecha)}</td><td class="reg-time-cell">${esc(r.hora||'--:--:--')}</td><td>${esc(mobiles.find(m=>m.id===r.movil_id)?.numero||'SIN MÓVIL')}</td><td><span class="reg-activity reg-activity-${color} entity-activity" data-entity-color="${validColor(r.actividad_color||activities.find(a=>a.id===r.actividad_id)?.color)}">${regIcon(icon)}<span>${esc(r.actividad_nombre)}</span></span></td><td>${esc(r.ubicacion||'—')}</td><td>${esc(r.detalle||'—')}</td><td><div class="reg-row-actions"><button type="button" data-reg-edit="${r.id}" class="reg-edit-action" title="Editar" aria-label="Editar registro ${r.id}">${regIcon('pencil')}</button><button type="button" data-reg-delete="${r.id}" class="reg-delete-action" title="Eliminar" aria-label="Eliminar registro ${r.id}">${regIcon('trash-2')}</button></div></td></tr>`}).join(''):'<tr><td colspan="7" class="reg-empty">No hay registros para esta consulta. Seleccione otra fecha o limpie los filtros.</td></tr>'}</tbody></table>`;
 applyEntityColors(host);
 host.querySelectorAll('[data-reg-edit]').forEach(button=>button.onclick=()=>{const item=rows.find(r=>r.id===Number(button.dataset.regEdit)),tr=button.closest('tr');tr.innerHTML=`<td colspan="7" class="reg-inline-edit"><form class="reg-record-form">${registryFields(item)}<div class="reg-form-actions"><button type="button" class="reg-tool-button" data-cancel-edit>Cancelar</button><button type="submit" class="reg-create-button">${regIcon('check')}Guardar cambios</button></div></form></td>`;const form=tr.querySelector('form');bindRegistryForm(form,item.id);form.querySelector('[data-cancel-edit]').onclick=renderRegistryTable});
 host.querySelectorAll('[data-reg-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('¿Eliminar este registro operativo? Esta acción no se puede deshacer.'))return;button.disabled=true;try{await api('registros/'+button.dataset.regDelete,'DELETE');notice('Registro eliminado');await refreshRegistryRows()}catch(e){notice(e.message);button.disabled=false}});
 document.querySelector('[data-record-range]').textContent=`Mostrando ${filtered.length?from+1:0} a ${Math.min(from+registryState.pageSize,filtered.length)} de ${filtered.length} registros`;
 const pager=document.querySelector('[data-reg-pagination]'),pageButton=(target,icon,label,disabled)=>`<button type="button" data-page="${target}" class="reg-page-button" aria-label="${label}" title="${label}" ${disabled?'disabled':''}>${regIcon(icon)}</button>`;
 pager.innerHTML=pageButton(1,'chevrons-left','Primera página',registryState.page===1)+pageButton(registryState.page-1,'chevron-left','Página anterior',registryState.page===1)+Array.from({length:Math.min(5,pages)},(_,i)=>Math.min(Math.max(1,registryState.page-2),Math.max(1,pages-4))+i).map(n=>`<button type="button" data-page="${n}" class="reg-page-button ${n===registryState.page?'active':''}" ${n===registryState.page?'aria-current="page"':''} aria-label="Página ${n}">${n}</button>`).join('')+pageButton(registryState.page+1,'chevron-right','Página siguiente',registryState.page===pages)+pageButton(pages,'chevrons-right','Última página',registryState.page===pages);
 pager.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{registryState.page=Number(button.dataset.page);renderRegistryTable()});
}
async function refreshRegistryRows(){
 if(!me||view!=='registros')return;const userId=me.id;const button=document.querySelector('[data-refresh-records]'),table=document.querySelector('#registry-table');if(button)button.disabled=true;if(table)table.setAttribute('aria-busy','true');
 try{const records=await api('registros');if(view!=='registros'||me?.id!==userId)return;rows=records;renderRegistryTable()}catch(e){notice(e.message)}finally{if(button)button.disabled=false;if(table)table.setAttribute('aria-busy','false')}
}
function updateRegistryContext(){
 if(!document.body.classList.contains('registry-layout')||!activeOperation)return;
 const context=activeOperation,jornada=context.jornada;registryClock={seconds:context.hora_local.split(':').reduce((n,v)=>n*60+Number(v),0),syncedAt:performance.now()};
 document.querySelector('[data-reg-date]').textContent=regDate(context.fecha_operativa);document.querySelector('[data-reg-shift]').textContent=shiftDescription(jornada).toUpperCase();document.querySelector('[data-reg-shift-icon]').innerHTML=regIcon(jornada.nombre==='Amanecida'?'moon':'sun');
 if(registryState.followDate&&registryState.date!==context.fecha_operativa){registryState.date=context.fecha_operativa;registryState.page=1;document.querySelector('[data-record-date]').value=registryState.date;renderRegistryTable()}
 const hour=document.querySelector('#edit [data-auto-hour]');if(hour&&hour.dataset.userEdited!=='true')hour.value=context.hora_local;
 paintRegistryClock();
}
function paintRegistryClock(){const clock=document.querySelector('[data-reg-clock]');if(!clock)return;const seconds=(registryClock.seconds+Math.floor((performance.now()-registryClock.syncedAt)/1000))%86400;clock.textContent=[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':')}
setInterval(paintRegistryClock,1000);
window.addEventListener('redeas:registros',()=>{if(me&&view==='registros'&&document.querySelector('#registry-table'))refreshRegistryRows()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('registry-menu-open')){document.body.classList.remove('registry-menu-open');const toggle=document.querySelector('[data-menu-toggle]');toggle?.setAttribute('aria-expanded','false');toggle?.focus()}});

window.addEventListener('resize',()=>{const nav=document.querySelector('.reg-topnav nav');if(nav)nav.inert=window.matchMedia('(max-width:900px)').matches&&!document.body.classList.contains('registry-menu-open')});
function validColor(value){return /^#[0-9a-f]{6}$/i.test(value||'')?value:'#0866E8'}
function colorInk(hex){const rgb=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#062B50':'#FFFFFF'}
function applyStationTheme(value){const color=validColor(value);let text=color,rgb=color.slice(1).match(/../g).map(v=>parseInt(v,16));while(colorInk(text)!=='#FFFFFF'){rgb=rgb.map(v=>Math.floor(v*.85));text='#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('')}for(const [key,val] of Object.entries({color,ink:colorInk(color),soft:color+'18',text}))document.documentElement.style.setProperty('--eas-'+key,val)}
function applyEntityColors(root=document){root.querySelectorAll('[data-entity-color]').forEach(node=>{const color=validColor(node.dataset.entityColor);node.style.setProperty('--entity-color',color);node.style.setProperty('--entity-ink',colorInk(color));node.style.setProperty('--entity-soft',color+'18')})}
const colorPalette=['#0866E8','#062B50','#087F8C','#25813B','#527A16','#C26900','#C52D41','#D12B55','#A23C99','#7C3AED','#5260AD','#64748B','#FFD21F','#FFFFFF'];
function colorEditor(value){const color=validColor(value);return `<fieldset class="color-editor"><legend>${view==='estaciones'?'Paleta de colores EAS':'Color de la actividad'}</legend><div class="color-editor-inputs"><label>Elegir color<input type="color" name="color" value="${color}"></label><label>Código hexadecimal<input name="color_hex" value="${color}" pattern="#[0-9a-fA-F]{6}" maxlength="7" required spellcheck="false"></label><span class="entity-color-preview" data-entity-color="${color}">Vista previa</span></div><div class="color-palette" aria-label="Paleta de colores sugeridos">${colorPalette.map(c=>`<button type="button" data-palette-color="${c}" data-entity-color="${c}" aria-label="Usar color ${c}" title="${c}"></button>`).join('')}</div><small>Seleccione una muestra, use la paleta o escriba un código #RRGGBB.</small></fieldset>`}
function bindColorEditor(form){const picker=form.elements.color,hex=form.elements.color_hex;if(!picker)return;const preview=form.querySelector('.entity-color-preview');function update(value){if(!/^#[0-9a-f]{6}$/i.test(value))return;picker.value=value;hex.value=value.toUpperCase();preview.dataset.entityColor=value;applyEntityColors(form)}picker.oninput=()=>update(picker.value);hex.oninput=()=>update(hex.value);form.querySelectorAll('[data-palette-color]').forEach(b=>b.onclick=()=>update(b.dataset.paletteColor));applyEntityColors(form)}
function renderRadioDirectory(){
 const host=document.querySelector('main>.card'),admin=me.rol==='admin';
 host.classList.add('radio-directory');
 host.innerHTML=`<div class="radio-directory-intro"><div class="radio-directory-mark">${regIcon('radio')}</div><div><h2>Equipo de radioperadores</h2><p>${admin?'Administra los nombres, su disponibilidad y las estaciones donde pueden operar.':'Consulta el equipo de tu estación y registra nuevos radioperadores.'}</p></div><span class="radio-directory-count">${rows.length} ${rows.length===1?'radioperador':'radioperadores'}</span></div><div class="radio-workspace"><section class="radio-form-panel" aria-labelledby="radio-form-title"><div class="radio-panel-heading"><span>${regIcon('plus')}</span><h3 id="radio-form-title" data-radio-form-title>Nuevo radioperador</h3></div><div id="editor"></div><p class="radio-form-note">${admin?'Un radioperador puede estar asignado a varias estaciones. Desactivarlo conserva sus reportes anteriores.':'El nombre se asignará a tu estación y estará disponible al iniciar sesión.'}</p></section><section class="radio-directory-panel" aria-labelledby="radio-directory-title"><div class="radio-panel-heading"><h3 id="radio-directory-title">Directorio</h3><span data-radio-count></span></div><div class="radio-directory-filters"><label class="radio-search">Buscar radioperador<input type="search" data-radio-search placeholder="Buscar por nombre…"></label>${admin?`<label>Estación<select data-radio-station><option value="">Todas las estaciones</option>${options(stations)}</select></label><label>Estado<select data-radio-state><option value="">Todos</option><option value="1">Habilitados</option><option value="0">Desactivados</option></select></label>`:''}</div><div class="radio-directory-results" data-radio-results></div></section></div>`;
 editor();
 const search=host.querySelector('[data-radio-search]'),station=host.querySelector('[data-radio-station]'),state=host.querySelector('[data-radio-state]');
 const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 function directory(){
  const filtered=rows.filter(r=>normalize(r.nombre).includes(normalize(search.value.trim()))&&(!station?.value||(r.estaciones||[r.estacion_id]).includes(Number(station.value)))&&(!state?.value||r.estado===Number(state.value)));
  host.querySelector('[data-radio-count]').textContent=`${filtered.length} de ${rows.length}`;
  const results=host.querySelector('[data-radio-results]');
  if(!filtered.length){results.innerHTML=`<div class="radio-directory-empty">${regIcon('radio')}<h3>${rows.length?'Sin coincidencias':'Aún no hay radioperadores'}</h3><p>${rows.length?'Prueba otro nombre o cambia los filtros.':'Agrega el primer nombre desde el formulario.'}</p></div>`;return}
  results.innerHTML=`<table class="radio-directory-table"><thead><tr><th>Radioperador</th><th>Estaciones asignadas</th><th>Estado</th>${admin?'<th>Acciones</th>':''}</tr></thead><tbody>${filtered.map(r=>{const initials=r.nombre.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('');return `<tr data-radio-id="${r.id}"><td data-label="Radioperador"><div class="radio-person"><span class="radio-avatar" aria-hidden="true">${esc(initials)}</span><div><strong>${esc(r.nombre)}</strong>${r.id===me.radiooperador?.id?'<small class="radio-current">En tu sesión</small>':''}</div></div></td><td data-label="Estaciones"><div class="radio-stations">${(r.estaciones||[r.estacion_id]).map(id=>{const s=stations.find(s=>s.id===id);return s?`<span data-entity-color="${validColor(s.color)}">${regIcon('building-2')}${esc(s.nombre)}</span>`:''}).join('')}</div></td><td data-label="Estado"><span class="radio-status ${r.estado?'enabled':'disabled'}"><span aria-hidden="true"></span>${r.estado?'Habilitado':'Desactivado'}</span></td>${admin?`<td data-label="Acciones"><div class="radio-actions"><button type="button" data-radio-edit="${r.id}" aria-label="Editar ${esc(r.nombre)}">${regIcon('pencil')}Editar</button><button type="button" data-radio-toggle="${r.id}" aria-label="${r.estado?'Desactivar':'Activar'} ${esc(r.nombre)}">${r.estado?'Desactivar':'Activar'}</button></div></td>`:''}</tr>`}).join('')}</tbody></table>`;
  applyEntityColors(results);
  results.querySelectorAll('[data-radio-edit]').forEach(button=>button.onclick=()=>{editor(rows.find(r=>r.id===Number(button.dataset.radioEdit)));host.querySelector('input[name=nombre]').focus()});
  results.querySelectorAll('[data-radio-toggle]').forEach(button=>button.onclick=async()=>{button.disabled=true;const r=rows.find(row=>row.id===Number(button.dataset.radioToggle));try{await api('radiooperadores/'+r.id,'PUT',{nombre:r.nombre,estado:r.estado?0:1,estaciones:r.estaciones});notice(r.estado?'Radioperador desactivado':'Radioperador habilitado');me=await api('me');await render()}catch(error){notice(error.message);button.disabled=false}});
 }
 search.oninput=directory;if(station)station.onchange=directory;if(state)state.onchange=directory;directory();
}
function kmLabel(value){return new Intl.NumberFormat('es-EC',{maximumFractionDigits:2}).format(value)}
function maintenanceCell(m){const info=m.mantenimiento_aceite;if(!info)return '—';return `<div class="oil-cell ${info.alerta?'oil-cell-alert':''}"><strong>${info.estado==='corresponde'?'Corresponde cambio':info.alerta?'Próximo mantenimiento':'Próximo cambio'} · ${kmLabel(info.proximo_km)} km</strong><small>${info.km_restantes===0?'Kilometraje de mantenimiento alcanzado':'Faltan '+kmLabel(info.km_restantes)+' km'}</small></div>`}
function renderMaintenanceAlerts(){
 const alerts=rows.filter(m=>m.mantenimiento_aceite?.alerta).sort((a,b)=>a.mantenimiento_aceite.km_restantes-b.mantenimiento_aceite.km_restantes);
 const panel=document.createElement('section');panel.className='oil-alert-panel';panel.setAttribute('aria-labelledby','oil-alert-title');
 panel.innerHTML=`<div class="oil-alert-heading"><div><h2 id="oil-alert-title">Cambio de aceite · cada 5.000 km</h2><p>Alerta desde 500 km antes del próximo mantenimiento, según el kilometraje registrado del móvil.</p></div><span class="oil-alert-count" role="status">${alerts.length?alerts.length+' '+(alerts.length===1?'móvil requiere atención':'móviles requieren atención'):'Sin alertas'}</span></div>${alerts.length?`<div class="oil-alert-list">${alerts.map(m=>`<article class="oil-alert-item ${m.mantenimiento_aceite.km_restantes===0?'oil-due':''}"><span class="oil-alert-icon" aria-hidden="true">${regIcon('truck')}</span><div><h3>Móvil ${esc(m.numero)} <small>${esc(m.placa)}</small></h3><p>${esc(stations.find(s=>s.id===m.estacion_id)?.nombre||'')} · Actual: <strong>${kmLabel(m.kilometraje)} km</strong> · Cambio de aceite: <strong>${kmLabel(m.mantenimiento_aceite.proximo_km)} km</strong></p><strong class="oil-remaining">${m.mantenimiento_aceite.km_restantes===0?'Corresponde realizar el cambio de aceite':'Faltan '+kmLabel(m.mantenimiento_aceite.km_restantes)+' km para el cambio de aceite'}</strong></div><button type="button" data-oil-edit="${m.id}">Editar kilometraje</button></article>`).join('')}</div>`:'<p class="oil-no-alerts">Ningún móvil está dentro de los 500 km previos al próximo cambio de aceite.</p>'}`;
 document.querySelector('#editor').before(panel);if(me.rol!=='admin'){const enter=document.createElement('button');enter.type='button';enter.className='vehicle-entry-button';enter.textContent='Registrar datos de jornada';enter.onclick=vehicleEntryPopup;panel.append(enter)}
 panel.querySelectorAll('[data-oil-edit]').forEach(button=>button.onclick=()=>{editor(rows.find(m=>m.id===Number(button.dataset.oilEdit)));const input=document.querySelector('#edit [name=kilometraje]');input.focus()});
}
async function vehicleEntryPopup(){
 if(document.querySelector('.vehicle-entry-dialog'))return;
 document.querySelectorAll('dialog[open]').forEach(d=>{d.close();d.remove()});
 const dialog=document.createElement('dialog');dialog.className='operator-dialog vehicle-entry-dialog';dialog.setAttribute('aria-labelledby','vehicle-entry-title');dialog.innerHTML='<h2 id="vehicle-entry-title">Móviles entrantes de la jornada</h2><p role="status">Consultando móviles pendientes…</p>';app.append(dialog);dialog.addEventListener('cancel',event=>event.preventDefault());dialog.showModal();
 async function enterRegistry(){me=await api('me');view='registros';dialog.close();dialog.remove();await render()}
 async function load(){if(dialog.saving)return;try{
  const data=await api('servicio-entrante');if(!dialog.isConnected)return;
  if(!Array.isArray(data.pendientes)||typeof data.clave!=='string')throw Error('El servidor sigue usando una versión anterior. Deténgalo con Ctrl+C, ejecute npm start y recargue con Ctrl+F5.');
  const fleet=data.moviles,active=data.contexto,pending=fleet.filter(m=>!m.completo),choices=pending.length?pending:fleet;
  dialog.dataset.jornadaClave=data.clave;applyStationTheme(data.estacion.color);scheduleShiftCheck(active);
  dialog.innerHTML=`<div class="vehicle-entry-step">INGRESO DE JORNADA · TODOS LOS MÓVILES</div><h2 id="vehicle-entry-title">Móviles entrantes de la jornada</h2><p class="vehicle-entry-context"><strong>${esc(data.estacion.nombre)}</strong> · ${regDate(active.fecha_operativa)}<br>${esc(active.jornada.nombre)} · ${esc(active.jornada.hora_inicio)}–${esc(active.jornada.hora_fin)}</p><div class="vehicle-entry-progress" role="status"><strong>${data.completados} de ${data.total} móviles completos</strong><span>${pending.length?'Pendientes: '+pending.length:'Todos los móviles de esta jornada tienen sus datos'}</span><progress max="${data.total||1}" value="${data.completados}" aria-label="Móviles completados"></progress></div>${fleet.length?`<form><label>${pending.length?'Móvil pendiente':'Móvil registrado'}<select name="movil_id" required>${choices.map(m=>`<option value="${m.id}">Móvil ${esc(m.numero)} · ${esc(m.placa)}</option>`).join('')}</select></label><div class="vehicle-entry-fields"><label>Nombre del conductor<input name="conductor" maxlength="200" required autocomplete="off"></label><label>Nombre del jefe de patrulla ACM<input name="jefe_patrulla" maxlength="200" required autocomplete="off"></label><label>Kilometraje entrante<input type="number" min="0" step="any" name="kilometraje" required></label><label>Combustible<select name="combustible" required><option value="">Seleccione combustible</option>${['Lleno','3/4','1/2','1/4','Reserva'].map(v=>`<option>${v}</option>`).join('')}</select></label></div><p class="vehicle-entry-note">Se guardará el servicio de este móvil y continuará el siguiente pendiente. La pantalla operativa se abrirá al completar todos.</p><p role="alert" data-entry-error></p><button type="submit">${pending.length>1?'Guardar y siguiente':'Guardar y abrir Registro Operativo'}</button></form>`:'<p>No hay móviles registrados en esta estación.</p><button type="button" data-register-mobile>Registrar móvil</button>'}<button type="button" class="secondary" data-entry-skip ${data.completo?'':'disabled'}>${data.completo?'Omitir · ya están todos completos':'Omitir (complete todos los móviles)'}</button><p class="vehicle-entry-skip-note">Al reingresar se conservan los datos de la jornada. Solo puede omitir si todos los móviles ya están completos.</p><button type="button" class="secondary" data-entry-logout>Cerrar sesión</button>`;
  dialog.scrollTop=0;
  dialog.querySelector('[data-entry-skip]').onclick=async()=>{const button=dialog.querySelector('[data-entry-skip]');button.disabled=true;try{await api('servicio-entrante/omitir','POST',{});await enterRegistry()}catch(error){notice(error.message);await load()}};
  dialog.querySelector('[data-entry-logout]').onclick=async()=>{try{await api('logout','POST');dialog.close();dialog.remove();login()}catch(error){notice(error.message)}};
  if(!fleet.length){dialog.querySelector('[data-register-mobile]').onclick=async()=>{dialog.close();dialog.remove();view='moviles';await render()};return}
  const form=dialog.querySelector('form'),select=form.elements.movil_id;
  function prefill(){const m=fleet.find(m=>m.id===Number(select.value));form.elements.conductor.value=m?.conductor||'';form.elements.jefe_patrulla.value=m?.jefe_patrulla||'';form.elements.kilometraje.value=m?.kilometraje_entrante??m?.kilometraje??'';form.elements.combustible.value=m?.combustible_entrante||m?.combustible||''}
  select.onchange=prefill;prefill();
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;dialog.saving=true;try{const result=await api('servicio-entrante','POST',{...Object.fromEntries(new FormData(form)),estacion_id:data.estacion.id,jornada_clave:data.clave});dialog.saving=false;if(result.ingreso_moviles.completo)await enterRegistry();else await load()}catch(error){dialog.saving=false;form.querySelector('[data-entry-error]').textContent=error.message;if(error.message.includes('jornada cambió')){notice(error.message);await load()}else button.disabled=false}};
 }catch(error){if(dialog.isConnected){dialog.innerHTML='<h2 id="vehicle-entry-title">Móviles entrantes de la jornada</h2><p role="alert"></p><button type="button">Reintentar</button>';dialog.querySelector('p').textContent=error.message;dialog.querySelector('button').onclick=load}}}
 dialog.reloadForShift=load;await load();
}
function renderRegistryMaintenance(){
 const main=document.querySelector('.reg-main');if(!main)return;
 main.querySelector('[data-registry-maintenance]')?.remove();
 const alerts=mobiles.filter(m=>m.estacion_id===registryStation()&&m.mantenimiento_aceite?.alerta).sort((a,b)=>a.mantenimiento_aceite.km_restantes-b.mantenimiento_aceite.km_restantes);if(!alerts.length)return;
 const section=document.createElement('section');section.className='reg-card maintenance-announcement';section.dataset.registryMaintenance='';section.setAttribute('aria-label','Avisos de mantenimiento de móviles');
 section.innerHTML=`<div class="maintenance-announcement-title"><svg class="maintenance-caution" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M10.3 3.8L1.8 18.5A2 2 0 0 0 3.5 21h17a2 2 0 0 0 1.7-2.5L13.7 3.8a2 2 0 0 0-3.4 0Z"/><path d="M12 8v5m0 3v1"/></svg><div><h2>Precaución · mantenimiento por cambio de aceite</h2><p>${alerts.length} ${alerts.length===1?'móvil requiere':'móviles requieren'} atención en ${esc(stations.find(s=>s.id===registryStation())?.nombre||'la estación')}.</p></div></div><ul>${alerts.map(m=>`<li><strong>Móvil ${esc(m.numero)} · ${esc(m.placa)}</strong><span>${kmLabel(m.kilometraje)} km · Cambio a los ${kmLabel(m.mantenimiento_aceite.proximo_km)} km</span><b>${m.mantenimiento_aceite.km_restantes===0?'Corresponde realizar el cambio de aceite':'Faltan '+kmLabel(m.mantenimiento_aceite.km_restantes)+' km'}</b></li>`).join('')}</ul><button type="button" data-open-maintenance>Ver móviles y mantenimiento</button>`;
 main.append(section);section.querySelector('button').onclick=()=>{view='moviles';render()};
}
async function refreshRegistryMaintenance(){
 if(!me||view!=='registros')return;const uid=me.id;try{const fleet=await api('moviles');if(!me||me.id!==uid||view!=='registros')return;mobiles=fleet;renderRegistryMaintenance()}catch{}
}
function renderReportsCenter(){
 const reports=[['gestion','Gestión operativa','Movimientos de las tres jornadas, por móvil, con hora, actividad, ubicación y novedades.','clipboard-list'],['diario','Consolidado diario','Conductor, jefe de patrulla, actividades, kilometraje y observaciones por móvil y jornada.','calendar-days'],['moviles','Móviles y mantenimiento','Flota asignada, circulación, combustible, novedades y kilómetros para el próximo cambio de aceite.','truck'],['ubicaciones','Ubicaciones y consignas','Catálogo de puntos y gráfico de los sectores con más actividades de los móviles.','map-pin'],['semanal','Operatividad semanal','Actividades de cada EAS por día, kilómetros por móvil y comparación con la semana anterior.','chart-no-axes-combined'],['radioperadores','Radioperadores','Asignaciones, fecha de creación, actividades por turno y móviles con mayor actividad.','radio']];
 const host=document.querySelector('main>.card');host.classList.add('reports-center');const date=activeOperation.fecha_operativa;
 host.innerHTML=`<div class="reports-intro"><div><h2>Descargar informes</h2><p>Selecciona el período y la estación. Cada informe está disponible en PDF y CSV.</p></div><span class="badge">America/Guayaquil</span></div><form class="reports-filters"><label>Desde<input type="date" name="desde" value="${date}" required></label><label>Hasta<input type="date" name="hasta" value="${date}" required></label><label>Estación EAS<select name="estacion_id" ${me.rol==='admin'?'':'disabled'}>${me.rol==='admin'?'<option value="">Todas las estaciones</option>':''}${options(stations,me.rol==='admin'?'':me.estacion_id)}</select></label></form><p class="reports-period-note">El informe semanal usa el lunes a domingo que contiene la fecha Desde y compara con la semana anterior. Los demás usan el período completo seleccionado.</p><div class="reports-cards">${reports.map(([key,name,description,icon])=>`<article class="reports-card"><span class="reports-card-icon">${regIcon(icon)}</span><h3>${name}</h3><p>${description}</p><div class="reports-downloads"><button type="button" data-report-type="${key}" data-report-format="pdf" aria-label="Descargar PDF de ${name}">Descargar PDF</button><button type="button" data-report-type="${key}" data-report-format="csv" aria-label="Descargar CSV de ${name}">Descargar CSV</button></div><p class="reports-download-status" data-export-status="${key}" role="status"></p></article>`).join('')}</div><div class="reports-data-note"><strong>Sobre los datos exportados</strong><p>El CSV utiliza UTF-8 y una columna sección para distinguir detalles, catálogos y resúmenes. Los históricos sin radioperador identificado permanecen sin atribuir. Los kilómetros pendientes no se estiman. Combustible representa el nivel registrado, no litros de abastecimiento.</p></div>`;
 const form=host.querySelector('form');form.onsubmit=event=>event.preventDefault();form.elements.estacion_id.onchange=()=>{const station=stations.find(s=>s.id===Number(form.elements.estacion_id.value));applyStationTheme(station?.color||stations.find(s=>s.id===registryStation())?.color)};
 host.querySelectorAll('[data-report-format]').forEach(button=>button.onclick=async()=>{
  if(!form.reportValidity())return;const type=button.dataset.reportType,format=button.dataset.reportFormat,status=host.querySelector(`[data-export-status=${type}]`),params=new URLSearchParams({tipo:type,formato:format,desde:form.elements.desde.value,hasta:form.elements.hasta.value});
  if(me.rol==='admin'&&form.elements.estacion_id.value)params.set('estacion_id',form.elements.estacion_id.value);
  button.disabled=true;status.textContent='Generando informe…';status.classList.remove('reports-error');
  try{const response=await fetch('/api/informes?'+params,{credentials:'same-origin'});if(!response.ok){const error=await response.json();if(response.status===401){login();return}throw Error(response.status===404&&error.error==='No encontrado'?'El servidor sigue en una versión anterior. Reinícielo con Ctrl+C y npm start, y recargue con Ctrl+F5.':error.error||'No se pudo generar el informe')}
   const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||`eas-go-${type}.${format}`;anchor.hidden=true;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Informe '+format.toUpperCase()+' descargado.';
  }catch(error){status.textContent=error.message;status.classList.add('reports-error')}finally{button.disabled=false}
 });
}
